--- Read searchable metadata from the generated index files.
--- Metadata filters are backed by the indexes only; notes' @document.meta is not consulted.
local indexers = require("neorg.modules.external.indexer.indexers")
local notes = require("neorg.modules.external.indexer.search_notes")

local M = {}

--- Workspace-relative paths of generated files and directories: the main index, the directories
--- of enabled indexers, and, when `root` is given, any configured indexer directory (enabled or
--- not) that contains the indexer marker file. When `root` is given, an existing directory without
--- the marker holds user notes and is not included.
--- @param config table external.indexer public configuration
--- @param root string|nil normalized workspace root
--- @return string[]
function M.generated_paths(config, root)
    local paths = { config.name }
    for _, ix in ipairs(indexers.enabled(config)) do
        local dir_abs = root and (root .. "/" .. ix.dir)
        if not dir_abs or vim.fn.isdirectory(dir_abs) ~= 1 or indexers.has_marker(dir_abs) then
            paths[#paths + 1] = ix.dir
        end
    end
    for _, dir in ipairs(root and indexers.marked_dirs(config, root) or {}) do
        if not vim.tbl_contains(paths, dir) then
            paths[#paths + 1] = dir
        end
    end
    return paths
end

local function read_lines(path)
    local file = io.open(path, "rb")
    if not file then
        return nil
    end
    local source = file:read("*a") or ""
    file:close()
    local lines = {}
    local in_meta = false
    for line in (source .. "\n"):gmatch("([^\n]*)\n") do
        line = line:gsub("\r$", "")
        -- Skip @document.meta so that its values never look like headings.
        if in_meta then
            in_meta = not line:match("^%s*@end%s*$")
        elseif line:match("^%s*@document%.meta") then
            in_meta = true
        else
            lines[#lines + 1] = line
        end
    end
    return lines
end

local function parse_heading(line)
    local stars, heading = line:match("^%s*(%*+)%s+(.-)%s*$")
    if stars then
        return #stars, heading
    end
end

--- Remove Norg backslash escapes from generated heading text.
local function unescape(text)
    return (text:gsub("\\(.)", "%1"))
end

-- Workspace links ({:$/path:}) point to notes; relative links are navigation.
local function note_path(heading)
    local target = heading:match("{:%$/(.-):}")
    return target and target .. ".norg"
end

--- Collect bucket values per note for one indexer.
--- @return table map of note relative path -> list of values
local function read_per_file(root, ix)
    local result = {}
    local dir_abs = vim.fs.normalize(root .. "/" .. ix.dir)
    -- Only directories generated by the indexer hold bucket files.
    if not indexers.has_marker(dir_abs) then
        return result
    end
    for name, kind in vim.fs.dir(dir_abs, { depth = math.huge }) do
        if kind == "file" and name:sub(-5) == ".norg" then
            local lines = read_lines(dir_abs .. "/" .. name)
            if lines then
                local path_parts = vim.tbl_map(indexers.decode_part, vim.split(name:sub(1, -6), "/", { plain = true }))
                local value
                for _, line in ipairs(lines) do
                    local _, heading = parse_heading(line)
                    if heading then
                        if value == nil then
                            value = ix.def.file_value(path_parts, unescape(heading), ix.config)
                        end
                        local path = note_path(heading)
                        if path and value then
                            result[path] = result[path] or {}
                            table.insert(result[path], value)
                        end
                    end
                end
            end
        end
    end
    return result
end

--- Collect bucket values per note from an indexer's inline section in the main index.
--- @return table map of note relative path -> list of values
local function read_inline(root, config, ix)
    local result = {}
    local lines = read_lines(vim.fs.normalize(root .. "/" .. config.name))
    if not lines then
        return result
    end
    local in_section = false
    local stack = {}
    for _, line in ipairs(lines) do
        local level, heading = parse_heading(line)
        if level and level <= 2 then
            in_section = level == 2 and heading == ix.def.title
            stack = {}
        elseif level and in_section then
            local path = note_path(heading)
            local depth = level - 2
            if path then
                -- An entry belongs to the bucket one level above it.
                local labels = vim.list_slice(stack, 1, depth - 1)
                if #labels == depth - 1 and #labels > 0 then
                    result[path] = result[path] or {}
                    table.insert(result[path], ix.def.inline_value(labels, ix.config))
                end
            else
                for i = depth, #stack do
                    stack[i] = nil
                end
                stack[depth] = unescape(heading)
            end
        end
    end
    return result
end

--- Keep only the most specific values: Notes sections also list descendants' notes.
local function drop_ancestors(values, separator)
    local unique, seen = {}, {}
    for _, value in ipairs(values) do
        if not seen[value] then
            seen[value] = true
            unique[#unique + 1] = value
        end
    end
    if not separator then
        return unique
    end
    local result = {}
    for _, value in ipairs(unique) do
        local prefix = value .. separator
        local ancestor = false
        for _, other in ipairs(unique) do
            if other:sub(1, #prefix) == prefix then
                ancestor = true
                break
            end
        end
        if not ancestor then
            result[#result + 1] = value
        end
    end
    return result
end

--- Read the metadata of all notes from the generated indexes.
--- @param root string normalized workspace root
--- @param config table external.indexer public configuration
--- @return table map of note relative path -> { [key] = text objects }
function M.read(root, config)
    local metadata = {}
    for _, ix in ipairs(indexers.enabled(config)) do
        local values = ix.per_file and read_per_file(root, ix) or read_inline(root, config, ix)
        local separator = ix.def.ancestor_separator(ix.config)
        for path, list in pairs(values) do
            metadata[path] = metadata[path] or {}
            metadata[path][ix.def.key] = vim.tbl_map(notes.text, drop_ancestors(list, separator))
        end
    end
    return metadata
end

return M
